string decode(const string &s) {
    vector<string> st(1);
    size_t i = 0;
    while (i < s.size()) {
        if (s[i] == '(') {
            st.emplace_back();
            i++;
        } else if (s[i] == ')') {
            string t = move(st.back());
            st.pop_back();
