import java.io.*;
import java.util.*;

public class Main {
    static String decode(String s) {
        ArrayDeque<StringBuilder> st = new ArrayDeque<>();
        st.push(new StringBuilder());
        int i = 0;
        while (i < s.length()) {
            char ch = s.charAt(i);
            if (ch == '(') {
                st.push(new StringBuilder());
                i++;
            } else if (ch == ')') {
                String t = st.pop().toString();
                i += 2;  // skip ")" and "{"
                int j = i;
                while (j < s.length() && Character.isDigit(s.charAt(j))) j++;
                long k = Long.parseLong(s.substring(i, j));
                i = j + 1;  // skip "}"
                StringBuilder top = st.peek();
                for (long r = 0; r < k; r++) top.append(t);
            } else {
                st.peek().append(ch);
                i++;
            }
        }
        return st.peek().toString();
    }

    public static void main(String[] args) throws IOException {
        BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
        int q = Integer.parseInt(in.readLine().trim());
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < q; i++) {
            String line = in.readLine();
            out.append(decode(line == null ? "" : line)).append('\n');
        }
        System.out.print(out);
    }
}

package main

import (
	"io"
	"os"
	"strconv"
	"strings"
)

func decode(s string) []byte {
	st := [][]byte{nil}
	i := 0
	for i < len(s) {
		switch s[i] {
		case '(':
			st = append(st, nil)
			i++
		case ')':
			t := st[len(st)-1]
			st = st[:len(st)-1]
			i += 2 // skip ")" and "{"
			j := i
			for j < len(s) && s[j] >= '0' && s[j] <= '9' {
				j++
			}
			k, _ := strconv.Atoi(s[i:j])
			i = j + 1 // skip "}"
			top := len(st) - 1
			for r := 0; r < k; r++ {
				st[top] = append(st[top], t...)
			}
		default:
			st[len(st)-1] = append(st[len(st)-1], s[i])
			i++
		}
	}
	return st[0]
}

func main() {
	raw, _ := io.ReadAll(os.Stdin)
	lines := strings.Split(strings.ReplaceAll(string(raw), "\r\n", "\n"), "\n")
	q, _ := strconv.Atoi(strings.TrimSpace(lines[0]))
	out := []byte{}
	for i := 1; i <= q; i++ {
		line := ""
		if i < len(lines) {
			line = lines[i]
		}
		out = append(out, decode(line)...)
		out = append(out, '\n')
	}
	os.Stdout.Write(out)
}
